contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function; takes no meaningful inputs but must be callable
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // call sudicideAnyone as owner (this contract is the owner)
        bool didRevert;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: either the call reverted, or C's balance became zero and this contract's
        // balance did not decrease (i.e., afterThis >= beforeThis)
        assert(didRevert || (afterC == 0 && afterThis >= beforeThis));
    }

    receive() external payable {}
}

