// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool didRevert;
        try c.sudicideAnyone() {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assertTrue(didRevert || (afterC == 0 && afterThis >= beforeThis));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
